&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt; line-height: 1;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;8’s, 10&#39;s, and 12&#39;s (full shift work)&lt;/span&gt;&lt;/li&gt;
